const expq = [['“길이 막혔길래 멈춘 트럭을 밀어서 치웠지.”', '“운전대 잡으니까 옛날 생각이 나더라고.”'], ['“지름길로 갔다가 길을 잃었어요. 대신 이상한 걸 찾았죠.”', '“제가 제일 먼저 도착했어요. 당연하죠.”'], ['“다친 사람 없어요. 제가 있는 한은요.”', '“폐허 약국에서 붕대를 한 상자 챙겼어요.”'], ['“무서웠는데 우산 쓰고 노래 불렀어요!”', '“돌아오는 길에 불빛을 세어 봤어요. 우리 마을이 제일 밝아요.”'], ['“폐허 화단에 들깨가 자라고 있더라꼬.”', '“젊은 아들보다 내가 더 잘 걷는다 아이가.”'], ['“주먹밥 싸 간 거 다들 두 개씩 먹었어.”', '“빈 식당 주방에 솥이 멀쩡하더라. 챙겨 왔지.”'], ['“저 다리, 조금만 손보면 건널 수 있겠어.”', '“무너진 벽 사이로 길을 냈다.”'], ['“폐허 벽에 누가 그린 해바라기가 있었어요.”', '“풍경을 스케치해 왔어요. 지도에 옮겨 둘게요.”'], ['“불씨가 남은 곳은 전부 꺼 두고 왔습니다.”', '“뒤쪽은 제가 맡았어요. 아무도 안 놓쳤어요.”'], ['“재 농도가 이상해요. 발전소에 가까울수록 짙어져요.”', '“…아무것도 아니에요. 그냥 기록만 해 뒀어요.”'], ['“가는 길 내내 방송 멘트를 연습했어요. 들어 볼래요?”', '“폐허 방송국에서 레코드판 몇 장을 챙겼어요.”'], ['“바람 방향이 바뀌기 전에 돌아왔어요. 제 말 맞죠?”', '“구름이 낮게 깔리는 쪽은 피해서 걸었어요.”'], ['“시계방 셔터가 반쯤 열려 있더군. 부품을 좀 챙겼지.”', '“천천히 걸어도 늦지 않았다네.”'], ['“가는 길 전선이 어떻게 이어져 있는지 다 봐 뒀어요.”', '“발전소 쪽 하늘은 아직 회색이에요. 그래도 조금 옅어졌어요.”'], ['“가는 길에 약초 세 뿌리 캤어요.”', '“모래 위 발자국은 거짓말을 안 해요.”'], ['“오는 길에 문 하나 용접해 두고 왔어.”', '“쓸 만한 쇠가 많더군.”'], ['“길은 제가 먼저 밟아 보고 왔어요.”', '“눈 밑 얼음 조심해요. 다들 무사해요.”'], ['“까마귀들이 안 쓰는 길로 왔어. 거긴 내가 다 알아.”', '“벽에 새 그림 있는 데는 이미 털린 데야. 그냥 지나쳤어.”'], ['“모래바람 속에서 길 잃을 뻔했어요.”', '“정비창 그늘에서 잠깐 쉬었어요.”'], ['“길에서 먹을 만한 풀을 찾았어요.”', '“물통이 모자랐어요.”'], ['“무거운 건 제가 들었어요.”', '“길가에 버려진 짐을 챙겼어요.”'], ['“등대 길로 돌아서 왔어요.”', '“등대 창고에서 부품을 주웠어요.”'], ['“공장 창고에서 쓸 만한 걸 찾았어요.”', '“라인 하나는 아직 돌릴 수 있어요.”'], ['“식량을 꼼꼼히 나눠 담았어요.”', '“통조림을 몇 개 찾았어요.”'], ['“끊어진 전선을 이어 왔어요.”', '“배전반에서 부품을 떼 왔어요.”'], ['“다친 사람 먼저 챙겼어요.”', '“약품 몇 개 챙겨 왔어요.”'], ['“눈길을 돌아서 왔어요.”', '“산장 창고를 털어 왔어요.”'], ['“길을 내면서 왔어요.”', '“눈 속에서 연료통을 찾았어요.”'], ['“아이들 이야기를 하며 걸었어요.”', '“마을회관 창고에서 공책을 찾았어요.”'], ['“산길로 질러 왔어요.”', '“감시탑에서 쓸 만한 걸 챙겼어요.”']];

