l], [6, '안테나는 높을수록 좋아. 철골은 내가 세울게.', 'sv6no10', null, null], [8, '높은 데 올라가는 건 제가 할게요. 원래 하던 일이에요.', 'sv8', null, null]], 'outro': [['me', '잡음 사이로 목소리가 들렸다. “…발전소… 아직… 누구 없나…”', null, null, null], ['me', '살아남은 건 우리만이 아니었다.', null, null, null], [10, '이제 방송은 여기서 할게요. 무전실 안테나면 훨씬 멀리까지 닿을 거예요.', 'sv10', null, null]]}]}, {'ch': '8장', 'title': '불빛의 도시', 'steps': [{'goal': '불빛의 도시 완성하기', 'rw': {'food': 100, 'plate': 40}, 'focus': 'center', 'hint': '전선·약품은 작업대에서 만들거나 벙커·원정에서 구해요', 'hl': '[data-act="shup"]', 'intro': [[0, '그 목소리에 답하려면 멀리서도 보이는 불이 있어야지. 쉘터를 끝까지 올려 보자고.', null, null, ['g', '그 목소리에 답하려면 멀리서도 보이는 불이 있어야 해. 쉘터를 끝까지 올려 보자.', null, null, null]], [9, '발전소까지 닿을 만큼 밝으면… 누군가 답할지도 몰라요.', null, null, null]], 'outro': [['me', '쉘터의 불빛이 구름을 뚫고 지평선까지 닿았다.', null, null, null], ['me', '멀리 발전소 쪽에서, 작은 불빛 하나가 깜빡이며 답했다.', null, null, null]]}, {'goal': '탁미영 맞이하기', 'rw': {'fuel': 30}, 'focus': null, 'hint': '발전소 쪽 빛을 따라 누군가 오고 있어요', 'hl': null, 'intro': [['me', '사흘 동안, 발전소 쪽 불빛이 쉘터 불빛에 같은 박자로 답했다.', null, null, null], ['me', '그런데 어젯밤, 재가 얕은 날마다 잡히던 기계 경보가 처음으로 멈췄다. 사람들이 웅성거렸다.', null, null, null], [11, '구름 흐름을 보면 그 불빛은 발전소 제어동 쪽이었어요. 내일은 바람도 이쪽으로 불어요. 누가 오기 딱 좋은 날씨예요.', 'sv11', null, null], [11, '…그 전날 저녁에도 구름이 이상했어요. 그런데 맑다고만 하라고 해서.', 'sv11', null, null], [9, '경보가 멈췄다는 건… 누가 발전소에서 뭔가를 꺼냈다는 거예요. 어쩌면, 이리로 오고 있는지도.', null, null, null]], 'outro': [[13, '이 불빛을 보고 왔어요. 이걸 품고요.', null, null, null], ['me', '미영이 품에서 꺼낸 것은 희미하게 빛나는 금속 원통이었다.', null, null, null], [13, '직원용 비상식량으로 버텼어요. 이 빛으로 재의 벽을 건너왔고요.', null, null, null], [13, '실험로의 심지예요. 꺼내는 데… 오래 망설였어요.', null, null, null], [13, '받아 줄 곳만 있으면 돼요. 이번엔 제대로.', null, null, null], ['me', '미영은 나를 보다가, 잠깐 말을 멈췄다.', null, null, null], [9, '…미영 씨. 살아 있었군요.', null, null, null], [13, '그날 재혁 씨는 떠났고, 저는 제어실에 남아 출력을 붙잡고 있었어요. 한동안 많이 원망했어요.', null, null, null], [13, '그런데 이 불빛을 보니까… 다시 해 볼 수 있을 것 같아요. 이번엔 같이요.', null, null, null], ['me', '두 사람은 한참 말이 없었다. 그러다 미영이 품에서 낡은 설계도를 꺼내 펼쳤다. 귀퉁이에 랜턴 밑바닥과 같은 문양이 찍혀 있었다.', null, null, null], [9, '…이 설계도, 기억나요. 원래… 다른 분이 그린 거예요.', null, null, null], ['me', '환영 자리에 은호만 보이지 않았다. 방송 준비 중이라고 했다.', 'sv10', null, null], ['me', '그날 밤, 미영은 심지를 품에 안은 채 잠들었다. 그 뒤로도 하룻밤도 내려놓지 않았다.', null, null, null]]}]}, {'ch': '9장', 'title': '등불 탑', 'steps': [{'goal': '등불 탑 토대 놓기', 'rw': {'batt': 2}, 'focus': 'center', 'hint': '쉘터 화면 ‘건설’ 맨 위 등불 탑에서 쌓아요', 'hl': '[data-act="tower"]', 'intro': [[9, '쉘터 한가운데 탑을 세워요. 미영 씨가 가져온 심지를 담아서, 그 빛을 구름 위로 쏘아 올릴 거예요.', null, null, null], [9, '설계도는 미영 씨가 지켜 왔어요. 쌓는 건… 모두의 몫이에요.', null, null, null]], 'outro': [['me', '토대에 모두의 이름을 새겼다. 아이들 이름도.', null, null, null]]}, {'goal': '등불 탑 기둥 세우기', 'rw': {'batt': 2}, 'focus': 'center', 'hint': '쉘터 화면 ‘건설’ 맨 위 등불 탑에서 쌓아요', 'hl': '[data-act="tower"]', 'intro': [['g', '기둥은 믿을 수 있는 손들이 붙잡아야 해. 서로 믿는 사람들 말이야.', null, null, null], [9, '그때 감싸 줘서… 고마웠어요. 이번 기둥은 제가 제일 먼저 붙잡을게요.', 'confA', null, null], [9, '말보다 손으로 갚겠다고 했죠. 기둥 용접은 제가 밤새 해 둘게요.', 'confB', null, null]], 'outro': [['me', '철골이 하늘로 뻗었다. 멀리서도 보일 만큼.', null, null, null]]}, {'goal': '등불 탑에 전선 잇기', 'rw': {'batt': 2}, 'focus': 'center', 'hint': '쉘터 화면 ‘건설’ 맨 위 등불 탑에서 쌓아요 · 연료가 모자라면 작업대 ‘숯 굽기’로 남는 목재를 태워요', 'hl': '[data-act="tower"]', 'intro': [[9, '발전기에서 탑 꼭대기까지 전선을 이어요. 마음이 모인 만큼 빛이 흘러요. …농담 아니에요.', null, null, null]], 'outro': [['me', '전선에 손을 대니 미세하게 떨렸다. 살아 있는 것처럼.', null, null, null]]}, {'goal': '등불 탑에 렌즈 올리기', 'rw': {'batt': 3}, 'focus': 'center', 'hint': '쉘터 화면 ‘건설’ 맨 위 등불 탑에서 쌓아요 · 약품은 작업대 3단계 ‘약초 달이기’로, 연료는 ‘숯 굽기’로 만들어요', 'hl': '[data-act="tower"]', 'intro': [[13, '이 렌즈가 빛을 모아요. 그런데… 그 랜턴, 잠깐 보여 줄래요?', null, null, null], [13, '역시. 등불 계획 첫 시제품, LP-001이에요.', null, null, null], [13, '겉은 기름불이지만 안에 든 건 작은 태양이에요. 재가 이 빛에만 걷혔던 이유예요.', null, null, null], [13, '…이 랜턴, 누구한테 받았어요?', null, null, null], ['me', '아버지가 그날 밤 맡기고 간 거라고 답했다.', null, null, null], [13, '…그렇군요.', null, null, null], ['me', '미영은 더 묻지 않았다. 대신 랜턴 밑바닥의 일련번호를 한참 들여다봤다.', null, null, null], [12, '…그 랜턴, 이 시계 뒷면이랑 같은 문양이구먼. 원래 주인 쪽으로 돌아가야 할 것 같소.', 'sv12', null, null]], 'outro': [['me', '처음부터 들고 있던 이 랜턴이, 모든 이야기의 시작이