const regionText = {'story': {'desert': [{'i': [['me', '모래 먼지 속에 녹슨 급유탑이 줄지어 서 있다. 품에 안은 불씨 상자가 아직 따뜻하다.', null, null, null], [0, '우선 우리 자리부터 밝히자고. 신호 보낸 사람이 어딘가 있을 거야.', null, null, ['g', '우선 우리 자리부터 밝히자. 신호 보낸 사람이 어딘가 있을 거야.', null, null, null]]], 'o': [['npc:desert', '정말 왔구먼! 불빛 보고 뛰어나왔소. 내가 라디오로 부른 급유탑지기 두식이오.', null, null, null], ['npc:desert', '저 급유탑 꼭대기 불? 우리가 켠 게 아니오. 원래부터 가끔, 혼자 켜졌지.', null, null, null]]}, {'i': [['npc:desert', '여긴 물이 귀해. 대신 기름은 넘친다오. 불이 꺼질 걱정은 없을 거요.', null, null, null]], 'o': [['me', '두 번째 판잣집. 처음보다 손이 훨씬 빨랐다.', null, null, null]]}, {'i': [['npc:desert', '마을 사람들이 급유탑 밑 지하 탱크에 숨어 있소. 연료를 모아 불을 밝혀 주면 나올 거요.', null, null, null]], 'o': [['npc:desert', '…저기 봐요. 사람들이 하나둘 올라오고 있어.', null, null, null]]}, {'i': [['npc:desert', '사막에 물이 없다는 건… 반은 거짓말이오.', null, null, null], ['npc:desert', '급유탑 밑 어딘가에 저수조가 있소. 다들 서로 못 믿어서 숨겨 버렸지.', null, null, null]], 'o': [['me', '모래 밑 철문을 열자, 서늘한 물 냄새가 올라왔다.', null, null, null], ['npc:desert', '…그래, 이거요. 마을 사람들이 숨겨 둔 저수조.', null, null, null]]}, {'i': [['npc:desert', '물이 있다는 소문은 금방 퍼지오. 오늘 밤, 물 도둑들이 올 거요.', null, null, null]], 'o': [['npc:desert', '막아 냈구먼. …그 도둑들도 목이 말랐을 뿐이오.', null, null, null]]}, {'i': [['npc:desert', '이 물을 어떻게 할지, 당신이 정해 주시오.', null, null, null], [14, '이 물이면 약초밭을 살릴 수 있어요.', null, null, null]], 'o': [['me', '결정은 내려졌다. 사막의 밤이 조금 덜 목마르다.', null, null, null]]}, {'i': [['g', '여기 사람들까지 지키려면 더 튼튼해야 해.', null, null, null]], 'o': [['npc:desert', '이 모래 도시에 벽이 선 건 처음이오.', null, null, null]]}, {'i': [[13, '여기서도 탑을 세울 수 있어요. 가져온 불씨면 충분해요.', null, null, ['me', '가져온 불씨면 충분하다. 여기서도 탑을 세울 수 있다.', null, null, null]]], 'o': [['me', '사막 한가운데, 두 번째 불빛의 도시가 섰다.', null, null, null]]}, {'i': [['npc:desert', '우리 손주들한테 별을 보여 줄 수 있을까?', null, null, null]], 'o': [['npc:desert', '…고맙소. 이 불은 이제 우리가 지키겠소.', null, null, null], ['me', '불씨는 나눈다고 줄지 않는다. 늘어날 뿐이다.', null, null, null]]}], 'factory': [{'i': [['me', '굴뚝이 숲처럼 서 있는 공단. 재가 가장 짙게 쌓인 곳이다.', null, null, null], ['g', '밤이 무서운 곳이라더군. 서둘러 불빛부터 켜자.', null, null, null]], 'o': [['npc:factory', '…빛? 진짜 빛이네. 공단 반장 마석이다. 여기선 다들 밤마다 싸우지.', null, null, null]]}, {'i': [['npc:factory', '재 괴물이 이틀에 한 번씩 몰려온다. 벽부터 세워.', null, null, null]], 'o': [['me', '철판이 넘치는 동네라, 판잣집 절반이 쇳덩이다.', null, null, null]]}, {'i': [['npc:factory', '우리도 같이 싸우겠다. 대신 버텨 내는 걸 보여 줘.', null, null, null]], 'o': [['npc:factory', '두 번을 버텼어. …좋아, 우리도 너희를 믿는다.', null, null, null]]}, {'i': [['npc:factory', '이상하지. 공단은 다 멈췄는데 3공장 굴뚝만 연기를 뿜어.', null, null, null], [9, '…설마.', null, null, null]], 'o': [['me', '쿵, 쿵. 아무도 없는 공장에서 기계가 돌아가고 있었다.', null, null, null], [9, '이건… 제가 설계한 등불 계획 부품 라인이에요. 재를 뿜으면서 아직도 돌고 있어요.', null, null, ['me', '재혁이 보여 준 도면이 떠올랐다. 등불 계획 부품 라인. 재를 뿜으며 아직도 돌고 있었다.', null, null, null]]]}, {'i': [['npc:factory', '네가 설계했다고? …좋아. 그럼 끄는 것도 네 몫이다.', 'sv9', null, ['npc:factory', '저 라인을 멈춰야 한다. 정문, 배관, 마지막 스위치. 너희 손을 빌리겠다.', null, null, null]], [15, '문은 내가 용접해서 뚫지.', null, null, null]], 'o': [['me', '마지막 스위치가 내려가자, 공단이 처음으로 조용해졌다.', null, null, null], ['npc:factory', '…고맙다. 그리고, 미안했다.', null, null, null]]}, {'i': [['npc:factory', '이제 저 라인을 어떻게 할 거냐.', null, null, null], [9, '부수는 게 맞을지도 몰라요. 하지만 고치면… 사람을 위한 걸 만들 수 있어요.', null, null, ['me', '부수면 재가 줄어든다. 고치면… 사람을 위한 걸 만들 수도 있다.', null, null, null]]], 'o': [['me', '공단의 굴뚝 하나가, 다른 이유로 연기를 내기 시작했다.', null, null, null]]}, {'i': [[9, '여기서 만든 렌즈가 다른 분소로도 갔어요. 몇 곳이나 되는지는… 저도 몰라요.', null, null, ['me', '이 공단에서 만든 렌즈가 다른 분소로도 갔다고 한다. 몇 곳인지는 아무도 모른다.', null, null, null]]], 'o': [['npc:factory', '그 계획 때문에 재가 왔다는 건 들었다. 그래도 불을 들고 온 건 너희다.', null, null, null]]}, {'i': [[0, '여기 사람들 손재주면 탑도 금방 올라가겠구먼.', null, null, ['g', '여기 사람들 손재주면 탑도 금방 올라가겠어.', null, null, null]]], 'o': [['me', '굴뚝 사이로 탑의 뼈대가 올라간다.', null, null, null]]}, {'i': [['npc:factory', '쇠 두드리는 소리가 오늘은 하나도 안 무섭군.', null, null, null]], 'o': [['npc:factory', '빛이다. 우리 공단에도.', null, null, null], ['me', '이 불은 마석이 지키기로 했다.', null, null, null]]}], 'snow': [{'i': [['me', '재 위에 눈이 내려 온 세상이 잿빛 눈밭이다.', null, null, null], ['g', '추위가 제일 무서워. 불부터 켜자.', null, null, null]], 'o': [['npc:snow', '어머, 불